// Built-in SYNTHETIC PRPD examples for the simulator (Tab 3).
// These are generated by simple, deterministic rules for teaching. They are NOT measurements.
//
// Editing guide: each example has `clusters`. A cluster creates `count` points with
//   phase  uniformly spread between phaseFrom..phaseTo (degrees; may wrap past 360)
//   magnitude following `shape`:
//     'flat'    -> uniform between magMin..magMax
//     'rising'  -> grows from magMin to magMax across the phase span (+ jitter)
//     'ear'     -> rises then falls ("rabbit-ear" look), peak at `peakAt` (0..1 of span)
//   jitter: random spread added to magnitude (a.u.)
// Magnitudes are in arbitrary units (a.u.), 0–100.

export const examples = [
  {
    id: 'internal',
    name: 'Internal (void) discharge',
    note: 'Synthetic. Two similar clusters on the rising slopes of both half-cycles, starting slightly before each zero crossing.',
    seed: 11,
    clusters: [
      { count: 70, phaseFrom: 345, phaseTo: 95, magMin: 12, magMax: 62, shape: 'ear', peakAt: 0.35, jitter: 9 },
      { count: 70, phaseFrom: 165, phaseTo: 275, magMin: 12, magMax: 60, shape: 'ear', peakAt: 0.35, jitter: 9 },
    ],
  },
  {
    id: 'surface',
    name: 'Surface discharge',
    note: 'Synthetic. Activity in both half-cycles but clearly asymmetric: larger, sparser pulses in one half-cycle and smaller, denser pulses in the other.',
    seed: 23,
    clusters: [
      { count: 35, phaseFrom: 15, phaseTo: 110, magMin: 30, magMax: 88, shape: 'rising', jitter: 12 },
      { count: 85, phaseFrom: 190, phaseTo: 285, magMin: 8, magMax: 32, shape: 'ear', peakAt: 0.5, jitter: 6 },
    ],
  },
  {
    id: 'corona',
    name: 'Corona (sharp point at HV, in air)',
    note: 'Synthetic. Many small pulses of nearly constant magnitude grouped around the negative peak (≈ 270°).',
    seed: 37,
    clusters: [
      { count: 110, phaseFrom: 240, phaseTo: 300, magMin: 9, magMax: 15, shape: 'flat', jitter: 2 },
    ],
  },
  {
    id: 'noise',
    name: 'Noise / interference',
    note: 'Synthetic. Pulses scattered across the whole cycle with no phase correlation — typical of random interference.',
    seed: 51,
    clusters: [
      { count: 110, phaseFrom: 0, phaseTo: 360, magMin: 3, magMax: 35, shape: 'flat', jitter: 4 },
    ],
  },
  {
    id: 'mixed',
    name: 'Mixed / ambiguous (void + corona)',
    note: 'Synthetic. Two sources at once. Shows why the comparison can be ambiguous and why real instruments separate sources first.',
    seed: 67,
    clusters: [
      { count: 45, phaseFrom: 350, phaseTo: 90, magMin: 15, magMax: 55, shape: 'ear', peakAt: 0.35, jitter: 8 },
      { count: 45, phaseFrom: 170, phaseTo: 270, magMin: 15, magMax: 55, shape: 'ear', peakAt: 0.35, jitter: 8 },
      { count: 70, phaseFrom: 245, phaseTo: 295, magMin: 9, magMax: 14, shape: 'flat', jitter: 2 },
    ],
  },
];

// Deterministic pseudo-random generator (mulberry32) so examples look the same every time.
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function generateExample(example) {
  const rand = rng(example.seed);
  const gauss = () => (rand() + rand() + rand() - 1.5) / 1.5; // approx. normal in [-1, 1]
  const points = [];
  for (const c of example.clusters) {
    const span = ((c.phaseTo - c.phaseFrom) + 360) % 360 || 360;
    for (let i = 0; i < c.count; i++) {
      const u = rand();
      const phase = (c.phaseFrom + u * span) % 360;
      let base;
      if (c.shape === 'rising') base = c.magMin + (c.magMax - c.magMin) * u;
      else if (c.shape === 'ear') {
        const p = c.peakAt ?? 0.4;
        const k = u < p ? u / p : 1 - (u - p) / (1 - p) * 0.75;
        base = c.magMin + (c.magMax - c.magMin) * k * (0.55 + 0.45 * rand());
      } else base = c.magMin + (c.magMax - c.magMin) * rand();
      const magnitude = Math.min(100, Math.max(0.5, base + gauss() * (c.jitter || 0)));
      points.push({ phase: +phase.toFixed(1), magnitude: +magnitude.toFixed(1) });
    }
  }
  return points;
}
